Action public RiskAssessment assessRisk(CreditFile file, BankAccounts accounts, OperationContext ctx) { return ctx.ai().withDefaultLlm() .createObject(&amp;#34;Assess credit risk using: &amp;#34; + file + accounts, RiskAssessment.class); } @AchievesGoal(description = &amp;#34;A credit decision with reasons&amp;#34;) @Action public CreditDecision writeDecision(Applicant a, RiskAssessment risk) { return policy.decide(a, risk); // deterministic rules } } Version noteCheck annotation names for your version Embabel&amp;rsquo;s documentation and examples use @Agent, @Action, @Condition and @AchievesGoal; some early material refers to @Goal. Follow the docs for the version you use. Good at: explainable, re-plannable flows; mixing LLM steps with deterministic Java; strong typing; Spring integration; replanning after each action when conditions change. Watch out: a newer project with a smaller community; think in types and preconditions rather than prompts. LangChain4j: AI Services and the agentic module# Core idea. Framework-agnostic Java (works with Quarkus, Micronaut, Spring, plain Java). AI Services turn an annotated interface into an LLM-backed implementation with tools, memory and RAG. The agentic module adds workflow patterns (sequence, parallel, loop, conditional) and a supervisor agent, plus MCP and A2A integration. interface CreditAnalyst { @SystemMessage(&amp;#34;You are a credit analyst. Be factual and concise.&amp;#34;) @UserMessage(&amp;#34;Assess this application: {{application}}&amp;#34;) @Agent(&amp;#34;Assesses SME credit applications&amp;#34;) String assess(@V(&amp;#34;application&amp;#34;) String application); } interface MemoWriter {
